+/**
+ * Check if the composer is full size
+ * @param event - The event object from the onContentSizeChange callback
+ * @param isFullComposerAvailable - Whether the composer is available in full size
+ * @param setIsFullComposerAvailable - A function to set the availability of the full composer
+ * @param numberOfLines - The number of lines in the text input
+ */
+function updateIsFullComposerAvailable(
+    event: TTextInputFocusEvent | null,
+    isFullComposerAvailable: boolean,
+    setIsFullComposerAvailable: (isFull: boolean) => void,
+    numberOfLines: number,
+    isComposerFullSize: boolean,
+): void {
+    if (!event) {
+        return;
+    }
+    const inputHeight = event.nativeEvent.contentSize.height;
+    if (!inputHeight) {
+        return;
+    }
+    const composerHeight = isComposerFullSize ? variables.composerMinHeight : 0;
+    const isFullComposer = !!(numberOfLines > 2 || inputHeight > composerHeight);
+    if (isFullComposerAvailable === isFullComposer) {
+        return;
+    }
+    setIsFullComposerAvailable(isFullComposer);
+}
